import{_ as a,a0 as l,w as o,s,ao as p,I as i,x as d,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux 中软链接和硬链接的区别 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中软链接和硬链接的区别 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中软链接和硬链接的区别 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中软链接和硬链接的区别 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200529 What is the Difference Between Soft link vs Hard link in Linux","title":"Linux 中软链接和硬链接的区别","tag":"202006","desc":""},"relativePath":"202006/20200529 What is the Difference Between Soft link vs Hard link in Linux.md","filePath":"[post].md"}'),u={name:"202006/20200529 What is the Difference Between Soft link vs Hard link in Linux.md"};function f(h,t,m,x,b,k){const e=l("Link");return o(),s("div",null,[t[15]||(t[15]=p('<h1 id="linux-中软链接和硬链接的区别" tabindex="-1">Linux 中软链接和硬链接的区别 <a class="header-anchor" href="#linux-中软链接和硬链接的区别" aria-label="Permalink to “Linux 中软链接和硬链接的区别”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202006/01/082717bilg8nmx808oxzgn.jpg" alt=""></p><p><ruby>链接<rt>Link</rt></ruby>是一种快捷访问机制，它通过一个文件指向原始文件或目录的方式实现快捷访问，同时还记录了原始文件或目录的一些信息。</p><p>链接允许多个不同文件对同一个文件进行引用。</p><h3 id="什么是软链接" tabindex="-1">什么是软链接 <a class="header-anchor" href="#什么是软链接" aria-label="Permalink to “什么是软链接”">​</a></h3><p><ruby>符号链接<rt>Symbolic Link</rt></ruby>（symlink），又称<ruby>软链接<rt>Soft Link</rt></ruby>，是一种特殊的文件，它指向 Linux 系统上的另一个文件或目录。</p><p>这和 Windows 系统中的快捷方式有点类似，链接文件中记录的只是原始文件的路径，并不记录原始文件的内容。</p><p>符号链接通常用于对库文件进行链接，也常用于链接日志文件和<ruby>网络文件系统<rt>Network File System</rt></ruby>（NFS）上共享的目录。</p><h3 id="什么是硬链接" tabindex="-1">什么是硬链接 <a class="header-anchor" href="#什么是硬链接" aria-label="Permalink to “什么是硬链接”">​</a></h3><p>硬链接是原始文件的一个镜像副本。创建硬链接后，如果把原始文件删除，链接文件也不会受到影响，因为此时原始文件和链接文件互为镜像副本。</p><p>为什么要创建链接文件而不直接复制文件呢？</p><p>当你需要将同一个文件保存在多个不同位置，而且还要保持持续更新的时候，硬链接的重要性就体现出来了。</p><p>如果你只是单纯把文件复制到另一个位置，那么另一个位置的文件只会保存着复制那一刻的文件内容，后续也不会跟随着原始文件持续更新。</p><p>而使用硬链接时，各个镜像副本的文件内容都会同时更新。</p><h3 id="软链接和硬链接的区别" tabindex="-1">软链接和硬链接的区别 <a class="header-anchor" href="#软链接和硬链接的区别" aria-label="Permalink to “软链接和硬链接的区别”">​</a></h3><p>下表列出了软链接和硬链接之间的区别。</p><div class="table-wrap"><table><thead><tr><th>#</th><th>软链接</th><th>硬链接</th></tr></thead><tbody><tr><td>1</td><td>软链接类似于 Windows 系统中的快捷方式</td><td>硬链接是原始文件的一个镜像副本</td></tr><tr><td>2</td><td>软链接又称符号链接</td><td>硬链接没有别名</td></tr><tr><td>3</td><td>链接中任何一个文件发生改变，都会同步到连接中的其它文件</td><td>和软链接一样</td></tr><tr><td>4</td><td>软链接可以跨文件系统进行创建</td><td>硬链接不可以跨文件系统进行创建</td></tr><tr><td>5</td><td>软链接可以指向文件或目录</td><td>硬链接只能指向文件</td></tr><tr><td>6</td><td>链接文件和原始文件之间的 inode 和文件权限不完全一致</td><td>链接文件和原始文件的 inode 和文件权限完全一致</td></tr><tr><td>7</td><td>链接文件只记录原始文件的路径，不记录原始文件的内容</td><td>链接文件记录了原始文件的内容</td></tr><tr><td>8</td><td>如果原始文件被移除，软链接就会因为指向不存在的文件而失效。这被称为“<ruby>挂起链接<rt>hanging link</rt></ruby>”</td><td>即使原始文件被移除，链接文件也不受影响。</td></tr><tr><td>9</td><td>通过 <code>ln -s &lt;原始文件&gt; &lt;链接文件&gt;</code> 命令创建软链接</td><td>通过 <code>ln &lt;原始文件&gt; &lt;链接文件&gt;</code> 命令创建硬链接</td></tr><tr><td>10</td><td>软链接文件的文件权限中有一个特殊标记 <code>l</code></td><td>硬链接文件没有特殊标记</td></tr><tr><td>11</td><td>通过 <code>find / -type l</code> 命令可以查找软链接文件</td><td>通过 <code>find / -samefile &lt;原始文件&gt;</code> 命令可以查找硬链接文件</td></tr><tr><td>12</td><td>通过 <code>symlinks &lt;目录&gt;</code> 命令可以查找失效的软链接</td><td>硬链接不存在失效链接</td></tr></tbody></table></div><hr>',18)),i("p",null,[t[1]||(t[1]=d("via: ",-1)),r(e,{href:"https://www.2daygeek.com/difference-between-soft-link-vs-hard-link-linux/"},{default:n(()=>[...t[0]||(t[0]=[d("https://www.2daygeek.com/difference-between-soft-link-vs-hard-link-linux/",-1)])]),_:1})]),i("p",null,[t[6]||(t[6]=d("作者：",-1)),r(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...t[2]||(t[2]=[d("Magesh Maruthamuthu",-1)])]),_:1}),t[7]||(t[7]=d(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[3]||(t[3]=[d("lujun9972",-1)])]),_:1}),t[8]||(t[8]=d(" 译者：",-1)),r(e,{href:"https://github.com/HankChow"},{default:n(()=>[...t[4]||(t[4]=[d("HankChow",-1)])]),_:1}),t[9]||(t[9]=d(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[d("wxy",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=d("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[d("LCTT",-1)])]),_:1}),t[13]||(t[13]=d(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[d("Linux中国",-1)])]),_:1}),t[14]||(t[14]=d(" 荣誉推出",-1))])])}const T=a(u,[["render",f]]);export{L as __pageData,T as default};
